WITH valid_customers AS (SELECT *, CASE WHEN city IN ('Berlin', 'Singapore') THEN 'Core' ELSE 'Other' END AS city_group FROM customers WHERE segment != 'Corporate' AND (is_active OR age = 58)), customers_stats AS (SELECT YEAR(signup_date) AS signup_year, city, COUNT(*) AS row_count FROM valid_customers GROUP BY YEAR(signup_date), city) SELECT signup_year, city, row_count FROM customers_stats ORDER BY row_count;
